mapper.select:
select * from oj_train_plan
where name = #{planName}
and create_user_id = #{userId}

select * from oj_train_plan
where 1=1

    and create_user_id = #{userId}


select * from ( SELECT a.`resource_id`,a.`name`,b.start_time,b.end_time,IFNULL(b.count,0) count,a.update_time,create_user_id FROM  `oj_train_plan` a left join

(SELECT min(start_time) start_time,max(end_time) end_time,count(1) count, train_plan_id,max(update_time)  update_time
FROM   oj_classroom
where 1=1

    and (create_user_id = #{userId}

        or (create_user_id = '3f655d87112f4ae094bbaf70830e20aa'

            and course_id in

                #{courseId}


        )

    )

group by train_plan_id) b
on a.resource_id = b.train_plan_id
where 1=1

    and a.create_user_id = #{userId}




    and a.resource_id in (select train_plan_id  FROM   oj_classroom where organization_id = #{organizationId})


union SELECT "${TASK_SET_ID}","${TASK_SET}",min(start_time) start_time,max(end_time) end_time,count(1) count, max(update_time)  update_time ,'-'
FROM   oj_classroom where train_plan_id = ''

    and create_user_id = #{userId}


    and organization_id = #{organizationId}

group by train_plan_id
) a where 1=1


and `name` like #{pattern}

select b.resource_id, b.name, c.paper_id, a.update_time, group_concat(a.resource_id SEPARATOR ',') as room_ids, count(a.lesson_id) as mission_count_total, count(c.paper_id) as course_practice_count_total, SUM(CASE WHEN c.`type` = 1 THEN 1 ELSE 0 END) AS experiment_report_count_total, min(a.start_time) as start_time, max(a.end_time) as end_time from oj_classroom as a left join oj_train_plan as b on a.train_plan_id = b.resource_id left join oj_course_lesson as c on a.lesson_id = c.resource_id where 1=1
and a.course_id in
#{courseId}
and b.`name` like #{pattern}
AND INSTR(a.organization_ids, CONCAT('\"', #{organizationId}, '\"')) > 0 group by a.train_plan_id
